from pathlib import Path
import re

path = Path('/home/ubuntu/marketing-agent-dashboard/frontend/index.html')
html = path.read_text()

old_markup = re.search(r'<section class="content-view" id="view-creative">.*?</section>', html, re.S)
if not old_markup:
    raise SystemExit('creative markup not found')

new_markup = '''<section class="content-view" id="view-creative"><div class="hero"><div class="eyebrow">❖ PERFIL CRIATIVO ARTÍSTICO</div><h1>Construa a identidade da <em>sua prática criativa</em></h1><p>Conte sua história, seu processo, seus materiais e seus objetivos. O perfil salvo aqui orienta automaticamente a personalidade, a linguagem e a direção de cada post gerado.</p></div><div class="creative-layout"><div class="panel creative-form"><div class="panel-head"><h2>Construção do Perfil Criativo</h2><span class="tag">USADO NOS POSTS</span></div><div class="creative-section"><div class="creative-section-head"><span class="creative-section-icon">◈</span><div><h3>Estilo de Arte</h3><p>A matéria, a linguagem e as referências que tornam seu trabalho reconhecível.</p></div></div><div class="creative-fields"><div class="field"><label>Estilo de Arte</label><textarea id="creative-art-style" placeholder="Descreva seu estilo artístico..."></textarea></div><div class="field"><label>Estilo Visual</label><textarea id="creative-visual-style" placeholder="Cores, composição, textura, acabamento e atmosfera..."></textarea></div><div class="field"><label>Materiais</label><textarea id="creative-materials" placeholder="Quais materiais você utiliza?"></textarea></div><div class="field"><label>Linguagem Visual</label><textarea id="creative-visual-language" placeholder="Figurativo, simbólico, abstrato..."></textarea></div><div class="field"><label>Inspirações</label><textarea id="creative-inspirations" placeholder="Suas referências e inspirações..."></textarea></div></div></div><div class="creative-section"><div class="creative-section-head"><span class="creative-section-icon">📚</span><div><h3>Trajetória</h3><p>As experiências e marcos que dão contexto à sua voz profissional.</p></div></div><div class="creative-fields"><div class="field"><label>Formação e Trajetória</label><textarea id="creative-formation" placeholder="Sua formação profissional..."></textarea></div><div class="field"><label>Anos de Experiência</label><input id="creative-years" placeholder="Ex.: 5, 10, 15..." /></div><div class="field"><label>Projetos Marcantes</label><textarea id="creative-projects" placeholder="Seus projetos mais importantes..."></textarea></div><div class="field"><label>Marcos Importantes</label><textarea id="creative-milestones" placeholder="Momentos importantes da sua carreira..."></textarea></div></div></div><div class="creative-section"><div class="creative-section-head"><span class="creative-section-icon">⚙️</span><div><h3>Processo Criativo</h3><p>Como você transforma uma ideia em uma experiência, obra ou entrega.</p></div></div><div class="creative-fields"><div class="field"><label>Descrição do Processo</label><textarea id="creative-process" placeholder="Como você trabalha..."></textarea></div><div class="field"><label>Ferramentas</label><textarea id="creative-tools" placeholder="Softwares, materiais, equipamentos..."></textarea></div><div class="field"><label>Tempo Médio de Execução</label><input id="creative-execution-time" placeholder="Ex.: 2-3 horas, 1 dia..." /></div><div class="field"><label>Abordagem Conceitual</label><textarea id="creative-conceptual-approach" placeholder="Como você desenvolve ideias..."></textarea></div></div></div><div class="creative-section"><div class="creative-section-head"><span class="creative-section-icon">💼</span><div><h3>Ideias de Negócio</h3><p>As possibilidades de produtos, serviços e parcerias para o próximo ciclo.</p></div></div><div class="creative-fields"><div class="field"><label>Ideias de Negócio</label><textarea id="creative-business-ideas" placeholder="Produtos ou serviços..."></textarea></div><div class="field"><label>Serviços Oferecidos</label><textarea id="creative-services" placeholder="Oficinas, consultoria, etc..."></textarea></div><div class="field"><label>Parcerias Desejadas</label><textarea id="creative-partnerships" placeholder="Tipos de colaborações..."></textarea></div><div class="field"><label>Objetivo de Longo Prazo</label><textarea id="creative-long-term-goal" placeholder="Seu sonho profissional..."></textarea></div></div></div><div class="creative-section"><div class="creative-section-head"><span class="creative-section-icon">👥</span><div><h3>Público-Alvo</h3><p>As pessoas que você deseja alcançar e o valor que seu trabalho oferece a elas.</p></div></div><div class="creative-fields"><div class="field"><label>Descrição do Público</label><textarea id="creative-audience" placeholder="Quem é seu público ideal..."></textarea></div><div class="field"><label>Valores do Público</label><textarea id="creative-audience-values" placeholder="O que seu público valoriza..."></textarea></div><div class="field"><label>Canais de Distribuição</label><textarea id="creative-distribution" placeholder="Onde você divulga, vende ou entrega seu trabalho..."></textarea></div></div></div><button class="primary" onclick="saveCreativeProfile()">✦ Salvar Perfil Criativo Artístico</button></div><div class="panel creative-summary-panel"><div class="panel-head"><h2>Perfil em uso</h2><span class="tag">CONTEXTO AUTOMÁTICO</span></div><div class="result" id="creative-summary">Preencha e salve o perfil para que sua trajetória, processo, negócio e público sejam usados automaticamente nas sugestões de posts.</div><div class="notice">O perfil é usado como contexto editorial e permanece editável. Revise os dados antes de gerar ou aprovar conteúdos.</div></div></div></section>'''
html = html[:old_markup.start()] + new_markup + html[old_markup.end():]

old_style_anchor = '.profile-active{margin:10px 0 14px;padding:10px 12px;border:1px solid #263b55;border-radius:8px;background:#0b1420;color:#9bcbe0;white-space:pre-wrap;font-size:11px;line-height:1.5}'
new_styles = old_style_anchor + ".creative-layout{display:grid;grid-template-columns:1.35fr .65fr;gap:15px;margin-top:24px}.creative-form{padding:20px}.creative-section{padding:18px 0;border-bottom:1px solid #20283a}.creative-section:first-of-type{padding-top:3px}.creative-section:last-of-type{border-bottom:0}.creative-section-head{display:flex;gap:11px;align-items:flex-start;margin-bottom:16px}.creative-section-icon{width:30px;height:30px;flex:0 0 30px;display:grid;place-items:center;border-radius:9px;background:rgba(135,87,232,.15);color:#b99aff;font-size:15px}.creative-section-head h3{font-family:Syne;font-size:14px;margin:0 0 4px;color:#eeeaff}.creative-section-head p{margin:0;color:#7f879c;font-size:11px;line-height:1.45}.creative-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 14px}.creative-fields .field{margin-bottom:13px}.creative-fields .field:last-child{margin-bottom:0}.creative-summary-panel{align-self:start;position:sticky;top:18px}.creative-summary-panel .result{white-space:pre-wrap;line-height:1.65}.creative-summary-line{color:#b9c2d6;font-size:12px}.creative-summary-label{color:#d1bdff;font-weight:700}@media(max-width:900px){.creative-layout{grid-template-columns:1fr}.creative-summary-panel{position:static}}@media(max-width:760px){.creative-fields{grid-template-columns:1fr}.creative-section{padding:16px 0}.creative-section-head h3{font-size:15px}.creative-section-head p{font-size:12px}.creative-form{padding:16px}}"
if old_style_anchor not in html:
    raise SystemExit('style anchor not found')
html = html.replace(old_style_anchor, new_styles, 1)

save_pattern = re.compile(r'function saveCreativeProfile\(\)\{.*?\}\nconst HISTORY_KEY=', re.S)
save_replacement = '''function saveCreativeProfile(){const ids=['artStyle','visualStyle','materials','visualLanguage','inspirations','formation','years','projects','milestones','process','tools','executionTime','conceptualApproach','businessIdeas','services','partnerships','longTermGoal','audience','audienceValues','distribution'];const profile={};ids.forEach(key=>{const el=document.getElementById('creative-'+key.replace(/[A-Z]/g,m=>'-'+m.toLowerCase()));profile[key]=el?el.value.trim():''});profile.personality=profile.artStyle||profile.visualStyle;profile.tone=profile.visualLanguage;profile.visual=profile.visualStyle||profile.artStyle;profile.guidelines=[profile.inspirations,profile.conceptualApproach,profile.audienceValues].filter(Boolean).join(' | ');localStorage.setItem(CREATIVE_PROFILE_KEY,JSON.stringify(profile));loadCreativeProfile();alert('Perfil Criativo artístico salvo. Ele será usado automaticamente nos próximos posts.')}\nconst HISTORY_KEY='''
if not save_pattern.search(html):
    raise SystemExit('save function not found')
html = save_pattern.sub(save_replacement, html, count=1)

load_pattern = re.compile(r'function loadCreativeProfile\(\)\{.*?\}\s*function readCreativeProfile\(\)', re.S)
load_replacement = '''function loadCreativeProfile(){const p=readCreativeProfile();const values={artStyle:p.artStyle||p.visual||'',visualStyle:p.visualStyle||p.visual||'',materials:p.materials||'',visualLanguage:p.visualLanguage||p.tone||'',inspirations:p.inspirations||p.guidelines||'',formation:p.formation||'',years:p.years||'',projects:p.projects||'',milestones:p.milestones||'',process:p.process||'',tools:p.tools||'',executionTime:p.executionTime||'',conceptualApproach:p.conceptualApproach||'',businessIdeas:p.businessIdeas||'',services:p.services||'',partnerships:p.partnerships||'',longTermGoal:p.longTermGoal||'',audience:p.audience||'',audienceValues:p.audienceValues||'',distribution:p.distribution||''};Object.entries(values).forEach(([key,value])=>{const el=document.getElementById('creative-'+key.replace(/[A-Z]/g,m=>'-'+m.toLowerCase()));if(el)el.value=value});const summary=document.getElementById('creative-summary');const active=document.getElementById('active-profile-summary');const filled=Object.values(values).filter(Boolean).length;if(summary){summary.textContent=filled?`Estilo de arte: ${values.artStyle||'não informado'}\\nEstilo visual: ${values.visualStyle||'não informado'}\\n\\nTrajetória: ${values.formation||'não informada'}${values.years?` · ${values.years} anos de experiência`:''}\\n\\nProcesso: ${values.process||'não informado'}\\n\\nNegócio: ${values.businessIdeas||'não informado'}\\n\\nPúblico-alvo: ${values.audience||'não informado'}\\nCanais: ${values.distribution||'não informados'}\\n\\nEste contexto será enviado automaticamente para as sugestões e variações de posts.`:'Preencha e salve o perfil para que sua trajetória, processo, negócio e público sejam usados automaticamente nas sugestões de posts.'}if(active)active.textContent=filled?`Perfil Criativo artístico ativo · ${values.artStyle||values.visualStyle||'estilo em construção'} · ${values.audience||'público ainda não definido'}`:'Nenhum Perfil Criativo salvo. Acesse Perfil Criativo para definir a personalidade usada nos posts.'}
function readCreativeProfile()'''
if not load_pattern.search(html):
    raise SystemExit('load function not found')
html = load_pattern.sub(load_replacement, html, count=1)

path.write_text(html)
print('creative-profile-expanded')
''
